import java.io.*;
import java.util.*;

public class C {

	BufferedReader reader;
	PrintWriter writer;
	StringTokenizer tokenizer;
	boolean endOfFile;

	void process() throws IOException {
		nextInt();
		String s = nextToken();
		writer.println(fast(s));
	}

	static final String BAD_CHARS = "VK";

	String normalize(String s) {
		StringBuilder sb = new StringBuilder();
		for (char c : s.toCharArray()) {
			if (BAD_CHARS.indexOf(c) >= 0) {
				sb.append(c);
			} else {
				sb.append('A');
			}
		}
		return sb.toString();
	}

	int slowMethod(String s) {
		s = normalize(s);
		Map<String, Integer> visited = new HashMap<>();
		ArrayDeque<String> queue = new ArrayDeque<>();
		queue.add(s);
		visited.put(s, 0);

		while (true) {
			String current = queue.poll();
			int dist = visited.get(current);
			if (current.indexOf(BAD_CHARS) == -1) {
				return dist;
			}
			for (int i = 0; i < current.length() - 1; i++) {
				String swapped = swapChars(current, i, i + 1);
				if (swapped != null && !visited.containsKey(swapped)) {
					visited.put(swapped, dist + 1);
					queue.add(swapped);
				}
			}
		}
	}

	String swapChars(String s, int i, int j) {
		if (s.charAt(i) == s.charAt(j)) return null;
		char[] arr = s.toCharArray();
		char tmp = arr[i];
		arr[i] = arr[j];
		arr[j] = tmp;
		return new String(arr);
	}

	static final String TARGET = "VKA";

	int fast(String s) {
		s = normalize(s);
		int length = s.length();
		int[] charIndices = new int[length];
		int[][] positions = new int[3][length];
		int[] sizes = new int[3];

		int[][][] countHere = new int[3][length][3];

		int[][] prefix = new int[length + 1][];
		prefix[0] = new int[] {0, 0, 0};

		for (int i = 0; i < length; i++) {
			charIndices[i] = TARGET.indexOf(s.charAt(i));
			int cIdx = charIndices[i];
			countHere[cIdx][sizes[cIdx]] = prefix[i].clone();
			positions[cIdx][sizes[cIdx]] = i;
			sizes[cIdx]++;
			prefix[i + 1] = prefix[i].clone();
			prefix[i + 1][cIdx]++;
		}

		int[][][][] dp = new int[2][sizes[0] + 1][sizes[1] + 1][sizes[2] + 1];
		for (int i = 0; i < 2; i++) {
			for (int j0 = 0; j0 <= sizes[0]; j0++) {
				for (int j1 = 0; j1 <= sizes[1]; j1++) {
					Arrays.fill(dp[i][j0][j1], INF);
				}
			}
		}

		int answer = INF;
		dp[0][0][0][0] = 0;

		for (int j0 = 0; j0 <= sizes[0]; j0++) {
			for (int j1 = 0; j1 <= sizes[1]; j1++) {
				for (int j2 = 0; j2 <= sizes[2]; j2++) {
					for (int last = 0; last < 2; last++) {
						int indexSum = j0 + j1 + j2;
						int currentCost = dp[last][j0][j1][j2];
						if (currentCost == INF) continue;
						if (indexSum == length) {
							answer = Math.min(answer, currentCost);
							continue;
						}
						if (j0 < sizes[0]) {
							int cost = Math.max(j1 - countHere[0][j0][1], 0)
									+ Math.max(j2 - countHere[0][j0][2], 0);
							dp[1][j0 + 1][j1][j2] = Math.min(dp[1][j0 + 1][j1][j2], currentCost + cost);
						}
						if (j1 < sizes[1] && last == 0) {
							int cost = Math.max(j0 - countHere[1][j1][0], 0)
									+ Math.max(j2 - countHere[1][j1][2], 0);
							dp[0][j0][j1 + 1][j2] = Math.min(dp[0][j0][j1 + 1][j2], currentCost + cost);
						}
						if (j2 < sizes[2]) {
							int cost = Math.max(j0 - countHere[2][j2][0], 0)
									+ Math.max(j1 - countHere[2][j2][1], 0);
							dp[0][j0][j1][j2 + 1] = Math.min(dp[0][j0][j1][j2 + 1], currentCost + cost);
						}
					}
				}
			}
		}
		return answer;
	}

	static final int INF = 1_000_000;

	String createRandomString() {
		Random rand = new Random(123);
		int n = 12;
		char[] buf = new char[n];
		for (int i = 0; i < n; i++) {
			buf[i] = TARGET.charAt(rand.nextInt(3));
		}
		return new String(buf);
	}

	void runStress() {
		Random rand = new Random(123);
		for (int t = 0;; t++) {
			String s = createRandomString();
			int fastRes = fast(s);
			int slowRes = slowMethod(s);
			if (fastRes != slowRes) {
				System.err.println("Discrepancy on: " + s);
				System.err.println("Fast: " + fastRes);
				System.err.println("Slow: " + slowRes);
				throw new AssertionError();
			}
			System.err.println("Test #" + t);
		}
	}

	C() throws IOException {
		reader = new BufferedReader(new InputStreamReader(System.in));
		writer = new PrintWriter(System.out);
		process();
		// runStress();
		writer.close();
	}

	public static void main(String[] args) throws IOException {
		new C();
	}

	String nextToken() {
		while (tokenizer == null || !tokenizer.hasMoreTokens()) {
			try {
				tokenizer = new StringTokenizer(reader.readLine());
			} catch (Exception e) {
				endOfFile = true;
				return null;
			}
		}
		return tokenizer.nextToken();
	}

	String nextLine() {
		try {
			return reader.readLine();
		} catch (IOException e) {
			endOfFile = true;
			return null;
		}
	}

	int nextInt() throws IOException {
		return Integer.parseInt(nextToken());
	}

	long nextLong() throws IOException {
		return Long.parseLong(nextToken());
	}

	double nextDouble() throws IOException {
		return Double.parseDouble(nextToken());
	}
}
